import React from "react";

export default function Slot({ slot }) {
  const color = slot.status === 1 ? "#e74c3c" : "#2ecc71";
  return (
    <div style={{
      width: 100, height: 70, margin: 10,
      background: color, color: "white",
      display: "flex", alignItems: "center", justifyContent: "center",
      borderRadius: 8, fontWeight: "bold"
    }}>
      #{slot.slot_id} {slot.status === 1 ? "Occupied" : "Free"}
    </div>
  );
}
